mapper.select:
SELECT
    b.*
FROM
    mes_building_inspection_team_user_link a
        INNER JOIN mes_building_inspection_team b ON a.inspection_team_id = b.id
        AND b.bool_delete_enum =
            FALSE LEFT JOIN mes_building_groups_inspection_team_link c ON b.id = c.inspection_team_id
        AND c.bool_delete_enum = FALSE
WHERE
    a.user_id = #{userId}
  AND c.groups_id = #{groupsId}
  AND b.process_id = #{processId}
  AND a.bool_delete_enum = FALSE;

SELECT b.*
FROM mes_building_inspection_team_user_link a
         INNER JOIN mes_building_inspection_team b ON a.inspection_team_id = b.id
    AND b.bool_delete_enum = FALSE
         LEFT JOIN mes_building_production_line_team_link c ON b.id = c.team_id and c.team_type = #{teamType}
    AND c.bool_delete_enum = FALSE
WHERE a.user_id = #{userId}
  AND c.production_line_id = #{lineId}
  AND b.process_id = #{processId}
  AND a.bool_delete_enum = FALSE;

select p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', pro.id 'process.id', pro.name 'process.name', a.serial_number, r.inspection_quantity, r.create_time inspectionTime from mes_building_produce_inspection_team_report r inner join mes_building_process pro on pro.id = r.process_id
inner join tech_artifact a on a.id = r.product_id and r.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
inner join tech_enclosure a on a.id = r.product_id and r.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
inner join contract_project p on p.id = a.project_id where r.bool_delete_enum = 0
AND r.in_year_month_day_date >= date_format(#{startDate}, '%Y-%m-%d')
AND r.in_year_month_day_date <= date_format(#{endDate}, '%Y-%m-%d')

SELECT team.* FROM mes_building_inspection_team team WHERE team.bool_delete_enum = 0 AND team.id IN ( SELECT link.inspection_team_id FROM mes_building_production_line line LEFT JOIN mes_building_groups gro ON gro.production_line_id = line.id AND gro.bool_delete_enum = 0 LEFT JOIN mes_building_groups_inspection_team_link link ON link.groups_id = gro.id AND link.bool_delete_enum = 0 WHERE line.bool_delete_enum = 0
AND line.id IN
#{item}
)
